export class I18nManager {
  public currentLang: Language = "en";
  private listeners: Array<(lang: Language) => void> = [];

  constructor() {
    this.currentLang = this.loadLanguage();
  }

  private loadLanguage(): Language {
    try {
      const saved = localStorage.getItem(STORAGE_LANG_KEY);
      if (saved === "pl" || saved === "en") {
        return saved;
      }
    } catch {
      // ignore
    }
    return "en";
  }

  public setLanguage(lang: Language): void {
    this.currentLang = lang;
    try {
      localStorage.setItem(STORAGE_LANG_KEY, lang);
    } catch {
      // ignore
    }
    this.applyTranslations();
    for (const listener of this.listeners) {
      listener(lang);
    }
  }

  public toggleLanguage(): Language {
    const next: Language = this.currentLang === "en" ? "pl" : "en";
    this.setLanguage(next);
    return next;
  }

  public t(key: string): string {
    return translations[this.currentLang]?.[key] ?? translations.en[key] ?? key;
  }

  public onLanguageChange(cb: (lang: Language) => void): void {
    this.listeners.push(cb);
  }

  public applyTranslations(): void {
    if (typeof document === "undefined") return;

    document.documentElement.lang = this.currentLang;

    // Tłumaczenie elementów z atrybutem data-i18n
    const elements = document.querySelectorAll<HTMLElement>("[data-i18n]");
    elements.forEach(el => {
      const key = el.getAttribute("data-i18n");
      if (!key) return;
      const translated = this.t(key);
      if (el.tagName === "INPUT" || el.tagName === "TEXTAREA") {
        (el as HTMLInputElement).placeholder = translated;
      } else {
        el.textContent = translated;
      }
    });

    // Tłumaczenie elementów z data-i18n-html (zawierające tagi <b> itp.)
    const htmlElements = document.querySelectorAll<HTMLElement>("[data-i18n-html]");
    htmlElements.forEach(el => {
      const key = el.getAttribute("data-i18n-html");
      if (!key) return;
      el.innerHTML = this.t(key);
    });

    // Tłumaczenie atrybutów title / aria-label
    const titleElements = document.querySelectorAll<HTMLElement>("[data-i18n-title]");
    titleElements.forEach(el => {
      const key = el.getAttribute("data-i18n-title");
      if (!key) return;
      el.title = this.t(key);
    });

    const ariaElements = document.querySelectorAll<HTMLElement>("[data-i18n-aria]");
    ariaElements.forEach(el => {
      const key = el.getAttribute("data-i18n-aria");
      if (!key) return;
      el.setAttribute("aria-label", this.t(key));
    });
  }
}

export const i18n = new I18nManager();
