// ═══════════════════════════════════════════════════════════════════
//  gpuContext.ts — Czysta i niezawodna inicjalizacja kontekstu WebGPU
// ═══════════════════════════════════════════════════════════════════

export interface GPUContextState {
  canvas: HTMLCanvasElement;
  adapter: GPUAdapter;
  device: GPUDevice;
  context: GPUCanvasContext;
  format: GPUTextureFormat;
  width: number;
  height: number;
  renderScale: number;
  deviceName: string;
}

export async function initGPUContext(
  canvasId: string = "canvas",
  initialRenderScale: number = 1.0,
): Promise<GPUContextState> {
  const canvas = document.getElementById(canvasId) as HTMLCanvasElement | null;
  if (!canvas) {
    throw new Error(`Nie znaleziono elementu canvas o id '${canvasId}'.`);
  }

  if (!navigator.gpu) {
    throw new Error("Twoja przeglądarka nie obsługuje WebGPU. Uruchom przeglądarkę Chromium z włączonym WebGPU.");
  }

  const adapter = await navigator.gpu.requestAdapter({
    // The powerPreference option is currently ignored when calling requestAdapter() on Windows. See https://crbug.com/369219127
    // initGPUContext @ :5173/src/gpuContext.ts?t=1790589018049:9
    powerPreference: "high-performance",
    forceFallbackAdapter: false, // true = wymuś ucieczkę do software GPU
    xrCompatible: false,
    featureLevel: "core",
  });

  if (!adapter) {
    throw new Error("Nie znaleziono kompatybilnej karty graficznej (GPU Adapter).");
  }

  // Pobranie nazwy i cech karty GPU
  let deviceName = "Domyślne GPU";
  try {
    const info = adapter.info;
    if (info && (info.description || info.device)) {
      deviceName = info.description || `${info.vendor} ${info.architecture || "GPU"}`;
    }
  } catch {
    // Adapter info may be restricted in some browser environments
  }

  const device = await adapter.requestDevice({
    requiredLimits: {
      maxStorageBufferBindingSize: adapter.limits.maxStorageBufferBindingSize,
      maxComputeWorkgroupStorageSize: adapter.limits.maxComputeWorkgroupStorageSize,
    },
  });

  device.lost.then(info => {
    console.error("WebGPU Device Lost:", info.reason, info.message);
  });

  device.addEventListener("uncapturederror", (event: Event) => {
    const errorEvent = event as GPUUncapturedErrorEvent;
    console.error("WebGPU Uncaptured Error:", errorEvent.error.message);
  });

  const context = canvas.getContext("webgpu");
  if (!context) {
    throw new Error("Nie można pobrać kontekstu WebGPU dla canvasu.");
  }

  const format = navigator.gpu.getPreferredCanvasFormat();

  // Wymiary wyznaczane z kontenera nadrzędnego canvasu
  const parent = canvas.parentElement || document.body;
  const clientWidth = parent.clientWidth || window.innerWidth;
  const clientHeight = parent.clientHeight || window.innerHeight;

  const dpr = Math.min(window.devicePixelRatio || 1, 2.0) * initialRenderScale;
  const width = Math.max(1, Math.floor(clientWidth * dpr));
  const height = Math.max(1, Math.floor(clientHeight * dpr));

  canvas.width = width;
  canvas.height = height;

  context.configure({
    device,
    format,
    alphaMode: "premultiplied",
  });

  return {
    canvas,
    adapter,
    device,
    context,
    format,
    width,
    height,
    renderScale: initialRenderScale,
    deviceName,
  };
}

export function updateCanvasSize(state: GPUContextState, newRenderScale?: number): boolean {
  if (typeof newRenderScale === "number") {
    state.renderScale = newRenderScale;
  }

  const parent = state.canvas.parentElement || document.body;
  const clientWidth = parent.clientWidth || window.innerWidth;
  const clientHeight = parent.clientHeight || window.innerHeight;

  const dpr = Math.min(window.devicePixelRatio || 1, 2.0) * state.renderScale;
  const newWidth = Math.max(1, Math.floor(clientWidth * dpr));
  const newHeight = Math.max(1, Math.floor(clientHeight * dpr));

  if (state.width !== newWidth || state.height !== newHeight) {
    state.width = newWidth;
    state.height = newHeight;
    state.canvas.width = newWidth;
    state.canvas.height = newHeight;

    state.context.configure({
      device: state.device,
      format: state.format,
      alphaMode: "premultiplied",
    });
    return true;
  }
  return false;
}
