// ═══════════════════════════════════════════════════════════════════
//  controls.ts — Moduł Kontrolera Kamery i Zdarzeń (Mysz, Dotyk, Klawiatura)
// ═══════════════════════════════════════════════════════════════════

import type { Camera3D } from "./camera";

export interface ControlsOptions {
  onResetSimulation?: () => void;
  onToggleFullscreen?: () => void;
  onToggleHUD?: () => void;
  onToggleShaderOverlay?: () => void;
  onTogglePause?: () => void;
  onStepFrame?: () => void;
  onSlower?: () => void;
  onFaster?: () => void;
}

export class OrbitControls {
  private canvas: HTMLCanvasElement;
  private camera: Camera3D;
  private options: ControlsOptions;

  public mouseX: number = 0;
  public mouseY: number = 0;
  public isMouseDown: boolean = false;

  private isDragging: boolean = false;
  private dragButton: number = 0;
  private isSpacePressed: boolean = false;

  // Stan dla obsługi gestów dotykowych (Touch)
  private activeTouches = new Map<number, { x: number; y: number }>();
  private initialPinchDistance: number | null = null;
  private lastMidpoint: { x: number; y: number } | null = null;

  // Cleanup listeners references
  private abortController = new AbortController();

  constructor(canvas: HTMLCanvasElement, camera: Camera3D, options: ControlsOptions = {}) {
    this.canvas = canvas;
    this.camera = camera;
    this.options = options;

    this.initEventListeners();
  }

  private initEventListeners(): void {
    const { signal } = this.abortController;

    // 1. Blokada menu kontekstowego na canvasie
    this.canvas.addEventListener("contextmenu", e => e.preventDefault(), { signal });

    // 2. Obsługa myszy (Desktop)
    this.canvas.addEventListener(
      "mousedown",
      (e: MouseEvent) => {
        this.isDragging = true;
        this.dragButton = e.button;
        this.updateNormalizedCoords(e.clientX, e.clientY);

        if (e.button === 0 && !this.isSpacePressed) {
          this.isMouseDown = true;
        }
      },
      { signal },
    );

    window.addEventListener(
      "mouseup",
      (e: MouseEvent) => {
        this.isDragging = false;
        if (e.button === 0) {
          this.isMouseDown = false;
        }
      },
      { signal },
    );

    window.addEventListener(
      "mousemove",
      (e: MouseEvent) => {
        this.updateNormalizedCoords(e.clientX, e.clientY);

        if (this.isDragging) {
          const dx = e.movementX;
          const dy = e.movementY;

          if (this.dragButton === 0 && !this.isSpacePressed) {
            // Lewy przycisk myszy: Obrót sferyczny (Orbit)
            this.camera.orbit(-dx * 0.005, -dy * 0.005);
          } else if (this.dragButton === 1 || this.dragButton === 2 || this.isSpacePressed) {
            // Prawy / środkowy przycisk myszy lub Spacja: Przesuwanie widoku (Pan)
            this.camera.pan(dx, dy);
          }
        }
      },
      { signal },
    );

    // Rolka myszy: Płynny zoom
    this.canvas.addEventListener(
      "wheel",
      (e: WheelEvent) => {
        e.preventDefault();
        const factor = e.deltaY > 0 ? 1.1 : 0.9;
        this.camera.zoom(factor);
      },
      { passive: false, signal },
    );

    // 3. Obsługa dotyku (Mobile Touch) — Bez przypadkowego odświeżania strony!
    this.canvas.addEventListener(
      "touchstart",
      (e: TouchEvent) => {
        // Blokujemy gesty systemowe przeglądarki (pull-to-refresh, page bounce)
        e.preventDefault();

        for (let i = 0; i < e.changedTouches.length; i++) {
          const t = e.changedTouches.item(i);
          if (t) {
            this.activeTouches.set(t.identifier, { x: t.clientX, y: t.clientY });
          }
        }

        if (e.touches.length === 1) {
          const firstTouch = e.touches.item(0);
          if (firstTouch) {
            this.updateNormalizedCoords(firstTouch.clientX, firstTouch.clientY);
            this.isMouseDown = true;
          }
        } else if (e.touches.length >= 2) {
          this.isMouseDown = false;
          const t1 = e.touches.item(0);
          const t2 = e.touches.item(1);
          if (t1 && t2) {
            this.initialPinchDistance = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            this.lastMidpoint = {
              x: (t1.clientX + t2.clientX) * 0.5,
              y: (t1.clientY + t2.clientY) * 0.5,
            };
          }
        }
      },
      { passive: false, signal },
    );

    this.canvas.addEventListener(
      "touchmove",
      (e: TouchEvent) => {
        // Blokujemy domyślne przewijanie i pull-to-refresh
        e.preventDefault();

        if (e.touches.length === 1) {
          // 1 palec: Płynny obrót kamery 3D (Orbit) oraz interakcja z cząstkami
          const touch = e.touches.item(0);
          if (touch) {
            const prev = this.activeTouches.get(touch.identifier);
            if (prev) {
              const dx = touch.clientX - prev.x;
              const dy = touch.clientY - prev.y;
              this.camera.orbit(-dx * 0.007, -dy * 0.007);
            }

            this.updateNormalizedCoords(touch.clientX, touch.clientY);
            this.activeTouches.set(touch.identifier, { x: touch.clientX, y: touch.clientY });
          }
        } else if (e.touches.length >= 2) {
          // 2 palce: Pinch-to-zoom oraz 2-finger Pan
          const t1 = e.touches.item(0);
          const t2 = e.touches.item(1);

          if (t1 && t2) {
            const currentDist = Math.hypot(t1.clientX - t2.clientX, t1.clientY - t2.clientY);
            const currentMidpoint = {
              x: (t1.clientX + t2.clientX) * 0.5,
              y: (t1.clientY + t2.clientY) * 0.5,
            };

            // Pinch zoom
            if (this.initialPinchDistance && this.initialPinchDistance > 5) {
              const scaleFactor = this.initialPinchDistance / Math.max(1, currentDist);
              const smoothFactor = 1.0 + (scaleFactor - 1.0) * 0.15;
              this.camera.zoom(smoothFactor);
              this.initialPinchDistance = currentDist;
            }

            // Two-finger Pan
            if (this.lastMidpoint) {
              const dx = currentMidpoint.x - this.lastMidpoint.x;
              const dy = currentMidpoint.y - this.lastMidpoint.y;
              this.camera.pan(dx, dy);
            }

            this.lastMidpoint = currentMidpoint;
          }
        }
      },
      { passive: false, signal },
    );

    const onTouchEnd = (e: TouchEvent) => {
      e.preventDefault();
      for (let i = 0; i < e.changedTouches.length; i++) {
        const item = e.changedTouches.item(i);
        if (item) {
          this.activeTouches.delete(item.identifier);
        }
      }

      if (e.touches.length === 0) {
        this.isMouseDown = false;
        this.initialPinchDistance = null;
        this.lastMidpoint = null;
      } else if (e.touches.length === 1) {
        const remaining = e.touches.item(0);
        if (remaining) {
          this.updateNormalizedCoords(remaining.clientX, remaining.clientY);
          this.isMouseDown = true;
        }
        this.initialPinchDistance = null;
        this.lastMidpoint = null;
      }
    };

    this.canvas.addEventListener("touchend", onTouchEnd, { passive: false, signal });
    this.canvas.addEventListener("touchcancel", onTouchEnd, { passive: false, signal });

    // 4. Skróty Klawiaturowe
    window.addEventListener(
      "keydown",
      (e: KeyboardEvent) => {
        const target = e.target as HTMLElement | null;
        if (target && (target.tagName === "INPUT" || target.tagName === "SELECT")) {
          return;
        }

        if (e.code === "Space") {
          this.isSpacePressed = true;
          e.preventDefault();
        } else if (e.code === "KeyR") {
          this.camera.reset();
          this.options.onResetSimulation?.();
        } else if (e.code === "KeyF") {
          this.options.onToggleFullscreen?.();
        } else if (e.code === "KeyH") {
          this.options.onToggleHUD?.();
        } else if (e.code === "KeyO") {
          this.options.onToggleShaderOverlay?.();
        } else if (e.code === "KeyP" || e.code === "KeyK") {
          this.options.onTogglePause?.();
        } else if (e.code === "Period") {
          this.options.onStepFrame?.();
        } else if (e.code === "BracketLeft") {
          this.options.onSlower?.();
        } else if (e.code === "BracketRight") {
          this.options.onFaster?.();
        }
      },
      { signal },
    );

    window.addEventListener(
      "keyup",
      (e: KeyboardEvent) => {
        if (e.code === "Space") {
          this.isSpacePressed = false;
        }
      },
      { signal },
    );
  }

  private updateNormalizedCoords(clientX: number, clientY: number): void {
    const rect = this.canvas.getBoundingClientRect();
    if (rect.width > 0 && rect.height > 0) {
      this.mouseX = ((clientX - rect.left) / rect.width) * 2.0 - 1.0;
      this.mouseY = 1.0 - ((clientY - rect.top) / rect.height) * 2.0;
    }
  }

  public destroy(): void {
    this.abortController.abort();
    this.activeTouches.clear();
  }
}
