// ═══════════════════════════════════════════════════════════════════
//  ui.ts — Moduł Interfejsu (Belka boczna/dolna, Uniformy, Ustawienia, HUD, i18n)
// ═══════════════════════════════════════════════════════════════════

import { i18n } from "./i18n";

export interface AppSettings {
  gravity: number; // 0.0 .. 2.0 g (E0, akceleracja wzdłuż osi do 2x 9.81 m/s²)
  vortexStrength: number; // 0.0 .. 5.0 A (natężenie prądu I drutu)
  damping: number; // 0.900 .. 1.000 (jakość próżni, 1.0 = brak tarcia)
  interactionRadius: number; // 0.5 .. 3.0 m (promień ekranu zewnętrznego R)
  pointSizeMultiplier: number; // 0.3 .. 3.0x
  glowIntensity: number; // 0.2 .. 3.0
  interactionMode: number; // 0 = negative probe (-Q), 1 = positive (+Q), 2 = dipole (Bz)
  colorScheme: number; // 0 = fizyczny
  particleCount: number; // 4096, 16384, 65536, 131072
  renderScale: number; // 0.5 .. 2.0
  timeScale: number; // 0.1 .. 2.0
  showShaderOverlay: boolean; // Winieta & celownik (Shader HUD)
  hudVisible: boolean; // Domyślnie widoczny panel sterowania
}

export const DEFAULT_SETTINGS: Readonly<AppSettings> = {
  gravity: 1.0, // 1.00 g (9.81 m/s²)
  vortexStrength: 1.5, // 1.50 A
  damping: 0.985, // 98.5% próżnia
  interactionRadius: 1.5, // R = 2.70 m
  pointSizeMultiplier: 1.0,
  glowIntensity: 1.0,
  interactionMode: 0,
  colorScheme: 0,
  particleCount: 16384,
  renderScale: 1.0,
  timeScale: 1.0,
  showShaderOverlay: false,
  hudVisible: true, // Zgodnie z wymaganiem: domyślnie WIDOCZNY
};

const STORAGE_KEY = "webgpu_ziemniak_settings_v5";

export interface UICallbacks {
  onResetSimulation: () => void;
  onParticleCountChange: (count: number) => void;
  onRenderScaleChange: (scale: number) => void;
  onTogglePause?: (isPaused: boolean) => void;
  onStepFrame?: () => void;
  onTimeScaleChange?: (scale: number) => void;
  onToggleHUD?: (visible: boolean) => void;
  onToggleShaderOverlay?: (visible: boolean) => void;
}

export class UIManager {
  public settings: AppSettings;
  private callbacks: UICallbacks;
  private saveTimeout: number | null = null;

  // Elementy DOM
  private elFps: HTMLElement | null = null;
  private elMs: HTMLElement | null = null;
  private elPoints: HTMLElement | null = null;
  private elRes: HTMLElement | null = null;
  private elGpuName: HTMLElement | null = null;
  private elSaveStatus: HTMLElement | null = null;

  // Suwaki i etykiety wartości
  private sliderGravity!: HTMLInputElement;
  private valGravity!: HTMLElement;
  private sliderVortex!: HTMLInputElement;
  private valVortex!: HTMLElement;
  private sliderDamping!: HTMLInputElement;
  private valDamping!: HTMLElement;
  private sliderRadius!: HTMLInputElement;
  private valRadius!: HTMLElement;
  private sliderSize!: HTMLInputElement;
  private valSize!: HTMLElement;
  private sliderGlow!: HTMLInputElement;
  private valGlow!: HTMLElement;
  private sliderScale!: HTMLInputElement;
  private valScale!: HTMLElement;
  private sliderTimeScale!: HTMLInputElement;
  private valTimeScale!: HTMLElement;

  private selectInteraction!: HTMLSelectElement;
  private selectParticles!: HTMLSelectElement;

  private checkShaderOverlay!: HTMLInputElement;

  // Przyciski w menu
  private btnPause!: HTMLButtonElement;
  private btnStep!: HTMLButtonElement;
  private btnResetSim!: HTMLButtonElement;
  private btnResetSettings!: HTMLButtonElement;
  private btnFullscreen!: HTMLButtonElement;
  private btnToggleHud!: HTMLButtonElement;
  private btnLangToggle!: HTMLButtonElement;

  // Przyciski dolne w belce menu
  private btnBarPause!: HTMLButtonElement;
  private btnBarHideMenu!: HTMLButtonElement;
  private btnBarFullscreen!: HTMLButtonElement;

  // Subtelny pasek szybkiego sterowania (widoczny przy schowanym menu lub na pełnym ekranie)
  private btnQuickMenu!: HTMLButtonElement;
  private btnQuickPause!: HTMLButtonElement;
  private btnQuickStep!: HTMLButtonElement;
  private btnQuickFs!: HTMLButtonElement;
  private quickPauseLabel!: HTMLElement;
  private quickFsLabel!: HTMLElement;

  public isPaused: boolean = false;

  constructor(callbacks: UICallbacks, gpuDeviceName?: string) {
    this.callbacks = callbacks;
    this.settings = this.loadSettings();

    this.bindDomElements();
    this.applySettingsToDom();
    this.attachEventListeners();

    if (gpuDeviceName && this.elGpuName) {
      this.elGpuName.textContent = gpuDeviceName;
    }

    // Inicjalizacja języka
    i18n.applyTranslations();
    this.updateLanguageButton();
  }

  private loadSettings(): AppSettings {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        return {
          ...DEFAULT_SETTINGS,
          ...parsed,
          hudVisible: true, // Zgodnie z wymaganiem: domyślnie widoczne
        };
      }
    } catch (err) {
      console.warn("Nie udało się odczytać ustawień z localStorage:", err);
    }
    return { ...DEFAULT_SETTINGS, hudVisible: true };
  }

  public saveSettings(): void {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.settings));
      this.showSaveNotification();
    } catch (err) {
      console.warn("Nie udało się zapisać ustawień do localStorage:", err);
    }
  }

  private showSaveNotification(): void {
    if (!this.elSaveStatus) return;
    this.elSaveStatus.classList.add("active");

    if (this.saveTimeout) {
      window.clearTimeout(this.saveTimeout);
    }

    this.saveTimeout = window.setTimeout(() => {
      this.elSaveStatus?.classList.remove("active");
    }, 1200);
  }

  private bindDomElements(): void {
    this.elFps = document.getElementById("stat-fps");
    this.elMs = document.getElementById("stat-ms");
    this.elPoints = document.getElementById("stat-points");
    this.elRes = document.getElementById("stat-res");
    this.elGpuName = document.getElementById("gpu-device-name");
    this.elSaveStatus = document.getElementById("save-status");

    this.sliderGravity = document.getElementById("slider-gravity") as HTMLInputElement;
    this.valGravity = document.getElementById("val-gravity") as HTMLElement;

    this.sliderVortex = document.getElementById("slider-vortex") as HTMLInputElement;
    this.valVortex = document.getElementById("val-vortex") as HTMLElement;

    this.sliderDamping = document.getElementById("slider-damping") as HTMLInputElement;
    this.valDamping = document.getElementById("val-damping") as HTMLElement;

    this.sliderRadius = document.getElementById("slider-radius") as HTMLInputElement;
    this.valRadius = document.getElementById("val-radius") as HTMLElement;

    this.sliderSize = document.getElementById("slider-size") as HTMLInputElement;
    this.valSize = document.getElementById("val-size") as HTMLElement;

    this.sliderGlow = document.getElementById("slider-glow") as HTMLInputElement;
    this.valGlow = document.getElementById("val-glow") as HTMLElement;

    this.sliderScale = document.getElementById("slider-scale") as HTMLInputElement;
    this.valScale = document.getElementById("val-scale") as HTMLElement;

    this.sliderTimeScale = document.getElementById("slider-timescale") as HTMLInputElement;
    this.valTimeScale = document.getElementById("val-timescale") as HTMLElement;

    this.selectInteraction = document.getElementById("select-interaction") as HTMLSelectElement;
    this.selectParticles = document.getElementById("select-particles") as HTMLSelectElement;

    this.checkShaderOverlay = document.getElementById("toggle-shader-overlay") as HTMLInputElement;

    // Przyciski w nagłówku i sekcjach
    this.btnPause = document.getElementById("btn-pause") as HTMLButtonElement;
    this.btnStep = document.getElementById("btn-step") as HTMLButtonElement;
    this.btnResetSim = document.getElementById("btn-reset-sim") as HTMLButtonElement;
    this.btnResetSettings = document.getElementById("btn-reset-settings") as HTMLButtonElement;
    this.btnFullscreen = document.getElementById("btn-fullscreen") as HTMLButtonElement;
    this.btnToggleHud = document.getElementById("btn-toggle-hud") as HTMLButtonElement;
    this.btnLangToggle = document.getElementById("btn-lang-toggle") as HTMLButtonElement;

    // Dolna belka akcji
    this.btnBarPause = document.getElementById("btn-bar-pause") as HTMLButtonElement;
    this.btnBarHideMenu = document.getElementById("btn-bar-hide-menu") as HTMLButtonElement;
    this.btnBarFullscreen = document.getElementById("btn-bar-fullscreen") as HTMLButtonElement;

    // Pływający pasek szybkiego sterowania
    this.btnQuickMenu = document.getElementById("btn-quick-menu") as HTMLButtonElement;
    this.btnQuickPause = document.getElementById("btn-quick-pause") as HTMLButtonElement;
    this.btnQuickStep = document.getElementById("btn-quick-step") as HTMLButtonElement;
    this.btnQuickFs = document.getElementById("btn-quick-fs") as HTMLButtonElement;
    this.quickPauseLabel = document.getElementById("quick-pause-label") as HTMLElement;
    this.quickFsLabel = document.getElementById("quick-fs-label") as HTMLElement;
  }

  private updateLanguageButton(): void {
    if (this.btnLangToggle) {
      this.btnLangToggle.textContent = i18n.currentLang.toUpperCase();
      this.btnLangToggle.title = i18n.t("btn.langToggle.title");
    }
  }

  private updateFormattedLabels(): void {
    // E0: wyświetlamy w g oraz m/s² (np. 1.00 g (9.8 m/s²), do 2.00 g (19.6 m/s²))
    if (this.valGravity) {
      const gVal = this.settings.gravity;
      const ms2 = gVal * 9.81;
      this.valGravity.textContent = `${gVal.toFixed(2)} g (${ms2.toFixed(1)} m/s²)`;
    }

    // I: natężenie prądu drutu w amperach
    if (this.valVortex) {
      this.valVortex.textContent = `${this.settings.vortexStrength.toFixed(2)} A`;
    }

    // Próżnia: procent jakości próżni (1.0 = 100%)
    if (this.valDamping) {
      this.valDamping.textContent = `${(this.settings.damping * 100).toFixed(1)}%`;
    }

    // Promień ekranu koncentrycznego: w metrach (promień R = U.interactionRadius * 1.8)
    if (this.valRadius) {
      this.valRadius.textContent = `${(this.settings.interactionRadius * 1.8).toFixed(2)} m`;
    }

    if (this.valSize) {
      this.valSize.textContent = `${this.settings.pointSizeMultiplier.toFixed(2)}×`;
    }

    if (this.valGlow) {
      this.valGlow.textContent = this.settings.glowIntensity.toFixed(2);
    }

    if (this.valScale) {
      this.valScale.textContent = `${this.settings.renderScale.toFixed(2)}×`;
    }

    if (this.valTimeScale) {
      this.valTimeScale.textContent = `${this.settings.timeScale.toFixed(2)}×`;
    }
  }

  private applySettingsToDom(): void {
    if (this.sliderGravity) this.sliderGravity.value = String(this.settings.gravity);
    if (this.sliderVortex) this.sliderVortex.value = String(this.settings.vortexStrength);
    if (this.sliderDamping) this.sliderDamping.value = String(this.settings.damping);
    if (this.sliderRadius) this.sliderRadius.value = String(this.settings.interactionRadius);
    if (this.sliderSize) this.sliderSize.value = String(this.settings.pointSizeMultiplier);
    if (this.sliderGlow) this.sliderGlow.value = String(this.settings.glowIntensity);
    if (this.sliderScale) this.sliderScale.value = String(this.settings.renderScale);
    if (this.sliderTimeScale) this.sliderTimeScale.value = String(this.settings.timeScale);

    this.updateFormattedLabels();
    this.updatePauseStateUI();

    if (this.selectInteraction) this.selectInteraction.value = String(this.settings.interactionMode);
    if (this.selectParticles) this.selectParticles.value = String(this.settings.particleCount);

    if (this.checkShaderOverlay) {
      this.checkShaderOverlay.checked = this.settings.showShaderOverlay;
    }

    if (this.elPoints) {
      this.elPoints.textContent = this.settings.particleCount.toLocaleString();
    }

    // Stan widoczności menu (HUD)
    const appEl = document.getElementById("app");
    if (appEl) {
      if (!this.settings.hudVisible) {
        appEl.classList.add("hud-hidden");
      } else {
        appEl.classList.remove("hud-hidden");
      }
    }
  }

  private updatePauseStateUI(): void {
    const pauseText = this.isPaused ? i18n.t("btn.resume") : i18n.t("btn.pause");
    const quickPauseText = this.isPaused ? i18n.t("float.play") : i18n.t("float.pause");

    if (this.btnPause) {
      this.btnPause.textContent = pauseText;
      this.btnPause.setAttribute("aria-pressed", String(this.isPaused));
    }
    if (this.btnBarPause) {
      this.btnBarPause.textContent = pauseText;
      this.btnBarPause.setAttribute("aria-pressed", String(this.isPaused));
    }
    if (this.quickPauseLabel) {
      this.quickPauseLabel.textContent = quickPauseText;
    }
  }

  private updateFullscreenUI(): void {
    const isFs = !!document.fullscreenElement;
    const fsText = isFs ? i18n.t("btn.exitFullscreen") : i18n.t("btn.fullscreen");
    const quickFsText = isFs ? i18n.t("float.fullscreenOff") : i18n.t("float.menu");

    if (this.btnBarFullscreen) {
      this.btnBarFullscreen.textContent = fsText;
    }
    if (this.quickFsLabel) {
      this.quickFsLabel.textContent = isFs ? i18n.t("float.fullscreenOff") : i18n.t("btn.fullscreen");
    }
  }

  private attachEventListeners(): void {
    // 1. Suwaki
    this.sliderGravity?.addEventListener("input", () => {
      this.settings.gravity = parseFloat(this.sliderGravity.value);
      this.updateFormattedLabels();
      this.saveSettings();
    });

    this.sliderVortex?.addEventListener("input", () => {
      this.settings.vortexStrength = parseFloat(this.sliderVortex.value);
      this.updateFormattedLabels();
      this.saveSettings();
    });

    this.sliderDamping?.addEventListener("input", () => {
      this.settings.damping = parseFloat(this.sliderDamping.value);
      this.updateFormattedLabels();
      this.saveSettings();
    });

    this.sliderRadius?.addEventListener("input", () => {
      this.settings.interactionRadius = parseFloat(this.sliderRadius.value);
      this.updateFormattedLabels();
      this.saveSettings();
    });

    this.sliderSize?.addEventListener("input", () => {
      this.settings.pointSizeMultiplier = parseFloat(this.sliderSize.value);
      this.updateFormattedLabels();
      this.saveSettings();
    });

    this.sliderGlow?.addEventListener("input", () => {
      this.settings.glowIntensity = parseFloat(this.sliderGlow.value);
      this.updateFormattedLabels();
      this.saveSettings();
    });

    this.sliderScale?.addEventListener("input", () => {
      this.settings.renderScale = parseFloat(this.sliderScale.value);
      this.updateFormattedLabels();
      this.saveSettings();
      this.callbacks.onRenderScaleChange(this.settings.renderScale);
    });

    this.sliderTimeScale?.addEventListener("input", () => {
      this.settings.timeScale = parseFloat(this.sliderTimeScale.value);
      this.updateFormattedLabels();
      this.saveSettings();
      this.callbacks.onTimeScaleChange?.(this.settings.timeScale);
    });

    // 2. Selecty
    this.selectInteraction?.addEventListener("change", () => {
      this.settings.interactionMode = parseInt(this.selectInteraction.value, 10);
      this.saveSettings();
    });

    this.selectParticles?.addEventListener("change", () => {
      const count = parseInt(this.selectParticles.value, 10);
      this.settings.particleCount = count;
      if (this.elPoints) this.elPoints.textContent = count.toLocaleString();
      this.saveSettings();
      this.callbacks.onParticleCountChange(count);
    });

    // 3. Winieta HUD
    this.checkShaderOverlay?.addEventListener("change", () => {
      this.settings.showShaderOverlay = this.checkShaderOverlay.checked;
      this.saveSettings();
      this.callbacks.onToggleShaderOverlay?.(this.settings.showShaderOverlay);
    });

    // 4. Język
    this.btnLangToggle?.addEventListener("click", () => {
      i18n.toggleLanguage();
      this.updateLanguageButton();
      this.updateFormattedLabels();
      this.updatePauseStateUI();
      this.updateFullscreenUI();
    });

    // 5. Przyciski akcji (Symulacja / Czas)
    this.btnPause?.addEventListener("click", () => this.togglePause());
    this.btnBarPause?.addEventListener("click", () => this.togglePause());
    this.btnQuickPause?.addEventListener("click", () => this.togglePause());

    this.btnStep?.addEventListener("click", () => this.stepFrame());
    this.btnQuickStep?.addEventListener("click", () => this.stepFrame());

    this.btnResetSim?.addEventListener("click", () => {
      this.callbacks.onResetSimulation();
    });

    this.btnResetSettings?.addEventListener("click", () => {
      this.resetSettingsToDefault();
    });

    // 6. Pełny ekran
    this.btnFullscreen?.addEventListener("click", () => this.toggleFullscreen());
    this.btnBarFullscreen?.addEventListener("click", () => this.toggleFullscreen());
    this.btnQuickFs?.addEventListener("click", () => this.toggleFullscreen());

    document.addEventListener("fullscreenchange", () => {
      this.updateFullscreenUI();
    });

    // 7. Pokazywanie / Ukrywanie Menu
    this.btnToggleHud?.addEventListener("click", () => this.toggleHUD());
    this.btnBarHideMenu?.addEventListener("click", () => this.toggleHUD(false));
    this.btnQuickMenu?.addEventListener("click", () => this.toggleHUD(true));
  }

  public togglePause(forceState?: boolean): void {
    const newState = forceState !== undefined ? forceState : !this.isPaused;
    this.isPaused = newState;
    this.updatePauseStateUI();
    this.callbacks.onTogglePause?.(this.isPaused);
  }

  public stepFrame(): void {
    if (!this.isPaused) {
      this.togglePause(true);
    }
    this.callbacks.onStepFrame?.();
  }

  public setTimeScale(scale: number): void {
    const clamped = Math.max(0.1, Math.min(2.0, Math.round(scale * 100) / 100));
    this.settings.timeScale = clamped;
    if (this.sliderTimeScale) {
      this.sliderTimeScale.value = String(clamped);
    }
    this.updateFormattedLabels();
    this.saveSettings();
    this.callbacks.onTimeScaleChange?.(clamped);
  }

  public adjustTimeScale(factor: number): void {
    this.setTimeScale(this.settings.timeScale * factor);
  }

  public toggleHUD(forceState?: boolean): void {
    const appEl = document.getElementById("app");
    if (!appEl) return;
    const newState = forceState !== undefined ? forceState : !this.settings.hudVisible;
    this.settings.hudVisible = newState;
    if (newState) {
      appEl.classList.remove("hud-hidden");
    } else {
      appEl.classList.add("hud-hidden");
    }
    this.saveSettings();
    this.callbacks.onToggleHUD?.(newState);
  }

  public toggleShaderOverlay(forceState?: boolean): void {
    const newState = forceState !== undefined ? forceState : !this.settings.showShaderOverlay;
    this.settings.showShaderOverlay = newState;
    if (this.checkShaderOverlay) {
      this.checkShaderOverlay.checked = newState;
    }
    this.saveSettings();
    this.callbacks.onToggleShaderOverlay?.(newState);
  }

  public resetSettingsToDefault(): void {
    // Menu pozostaje domyślnie WIDOCZNE po resecie
    this.settings = { ...DEFAULT_SETTINGS, hudVisible: true };
    localStorage.removeItem(STORAGE_KEY);
    if (this.isPaused) {
      this.togglePause(false);
    }
    this.applySettingsToDom();
    this.saveSettings();

    this.callbacks.onParticleCountChange(this.settings.particleCount);
    this.callbacks.onRenderScaleChange(this.settings.renderScale);
    this.callbacks.onTimeScaleChange?.(this.settings.timeScale);
    this.callbacks.onToggleShaderOverlay?.(this.settings.showShaderOverlay);
    this.toggleHUD(true);
  }

  public toggleFullscreen(): void {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().catch(err => {
        console.warn("Fullscreen error:", err);
      });
    } else {
      document.exitFullscreen().catch(err => {
        console.warn("Exit fullscreen error:", err);
      });
    }
  }

  public updateStats(fps: number, frameTimeMs: number, width: number, height: number): void {
    if (this.elFps) {
      this.elFps.textContent = `${Math.round(fps)}`;
      if (fps >= 55) {
        this.elFps.className = "stat-val green";
      } else if (fps >= 30) {
        this.elFps.className = "stat-val yellow";
      } else {
        this.elFps.className = "stat-val red";
      }
    }

    if (this.elMs) {
      this.elMs.textContent = `${frameTimeMs.toFixed(1)} ms`;
    }

    if (this.elRes) {
      this.elRes.textContent = `${width}×${height}`;
    }
  }
}
