// ═══════════════════════════════════════════════════════════════════
//  simulation.ts — Moduł Symulacji Cząstek (Compute Pipeline, Ping-Pong)
// ═══════════════════════════════════════════════════════════════════

import computeShaderCode from "./_compute.wgsl";

export interface SimulationManager {
  numPoints: number;
  uniformsBuffer: GPUBuffer;
  step: (commandEncoder: GPUCommandEncoder, uniformsData: Float32Array<ArrayBuffer>) => void;
  writeUniforms: (uniformsData: Float32Array<ArrayBuffer>) => void;
  getActiveReadBuffer: () => GPUBuffer;
  resetPoints: () => void;
  setParticleCount: (newCount: number) => void;
  updateShader?: (newShaderCode: string) => Promise<boolean> | boolean;
}

export function createSimulation(
  device: GPUDevice,
  initialPoints: number = 16384,
): SimulationManager {
  // Rozmiar pojedynczego punktu w bajtach (4 x vec4 = 16 floatów = 64 bajty)
  const POINT_SIZE_BYTES = 64;

  let currentPoints = initialPoints;
  let pointsBufferSize = currentPoints * POINT_SIZE_BYTES;

  // 1. Bufor Uniforms dla Compute Shadera (80 bajtów = 20 floatów)
  const uniformsBuffer = device.createBuffer({
    label: "Compute Uniforms Buffer",
    size: 80,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  });

  // 2. Shader Module i Compute Pipeline
  const computeModule = device.createShaderModule({
    label: "Simulation Compute Module",
    code: computeShaderCode,
  });

  const bindGroupLayout = device.createBindGroupLayout({
    label: "Simulation Bind Group Layout",
    entries: [
      {
        binding: 0,
        visibility: GPUShaderStage.COMPUTE,
        buffer: { type: "uniform" },
      },
      {
        binding: 1,
        visibility: GPUShaderStage.COMPUTE,
        buffer: { type: "read-only-storage" },
      },
      {
        binding: 2,
        visibility: GPUShaderStage.COMPUTE,
        buffer: { type: "storage" },
      },
    ],
  });

  const pipelineLayout = device.createPipelineLayout({
    label: "Simulation Pipeline Layout",
    bindGroupLayouts: [bindGroupLayout],
  });

  let computePipeline = device.createComputePipeline({
    label: "Simulation Compute Pipeline",
    layout: pipelineLayout,
    compute: {
      module: computeModule,
      entryPoint: "cs_main",
    },
  });

  const updateShader = async (newShaderCode: string): Promise<boolean> => {
    device.pushErrorScope("validation");
    const newModule = device.createShaderModule({
      label: "Simulation Compute Module (HMR)",
      code: newShaderCode,
    });
    const compileError = await device.popErrorScope();
    if (compileError) {
      console.warn("⚠️ [HMR] Błąd kompilacji _compute.wgsl:\n", compileError.message);
      return false;
    }

    device.pushErrorScope("validation");
    try {
      const newPipeline = await device.createComputePipelineAsync({
        label: "Simulation Compute Pipeline (HMR)",
        layout: pipelineLayout,
        compute: {
          module: newModule,
          entryPoint: "cs_main",
        },
      });

      const pipelineError = await device.popErrorScope();
      if (pipelineError) {
        console.warn("⚠️ [HMR] Błąd pipeline _compute.wgsl:\n", pipelineError.message);
        return false;
      }

      computePipeline = newPipeline;
      console.log("🔥 [HMR] Compute WGSL shader zaktualizowany na żywo!");
      return true;
    } catch (err) {
      await device.popErrorScope();
      console.warn("⚠️ [HMR] Błąd tworzenia pipeline _compute.wgsl:", err);
      return false;
    }
  };

  // 3. Bufory Ping-Pong i BindGroups
  let bufferA: GPUBuffer;
  let bufferB: GPUBuffer;
  let bindGroupAtoB: GPUBindGroup;
  let bindGroupBtoA: GPUBindGroup;
  let pingPong = true;

  // Inicjalizacja cząstek w geometrii cylindrycznej przewodu koncentrycznego
  function initPointsData(count: number): Float32Array<ArrayBuffer> {
    const data = new Float32Array(count * 16);
    const X_HALF = 3.8;
    const WIRE_A = 0.12;
    const SHIELD_R = 2.5;

    for (let i = 0; i < count; i++) {
      const offset = i * 16;

      // 1. Położenie wzdłuż osi przewodu X: [-X_HALF, X_HALF]
      const x = (Math.random() * 2.0 - 1.0) * X_HALF;

      // 2. Rozkład promieniowy po polu koła (równomierna gęstość)
      const r = Math.sqrt(WIRE_A * WIRE_A * 1.05 + Math.random() * (SHIELD_R * SHIELD_R * 0.95 - WIRE_A * WIRE_A));
      const theta = Math.random() * Math.PI * 2.0;

      const y = r * Math.cos(theta);
      const z = r * Math.sin(theta);
      const pointSize = 0.014 + Math.random() * 0.024;

      // 3. Prędkość początkowa: azymutalny dryf wokół przewodu + minimalny ruch osiowy
      const vDrift = 0.4 + Math.random() * 0.7;
      const vx = (Math.random() - 0.5) * 0.15;
      const vy = -Math.sin(theta) * vDrift;
      const vz = Math.cos(theta) * vDrift;
      const speed = Math.hypot(vx, vy, vz);

      data[offset + 0] = x;
      data[offset + 1] = y;
      data[offset + 2] = z;
      data[offset + 3] = pointSize;

      data[offset + 4] = vx;
      data[offset + 5] = vy;
      data[offset + 6] = vz;
      data[offset + 7] = speed;

      // 4. Kolor bazowy
      data[offset + 8] = 0.25;
      data[offset + 9] = 0.7;
      data[offset + 10] = 1.0;
      data[offset + 11] = 1.0;

      // 5. Parametry cząstki (masa, faza 5D, gęstość, id)
      data[offset + 12] = 0.8 + Math.random() * 0.4; // masa
      data[offset + 13] = Math.random() * Math.PI * 2.0; // psi (5. wymiar)
      data[offset + 14] = 0.0;
      data[offset + 15] = i;
    }

    return data;
  }

  function setupBuffers(count: number): void {
    if (bufferA) bufferA.destroy();
    if (bufferB) bufferB.destroy();

    currentPoints = count;
    pointsBufferSize = currentPoints * POINT_SIZE_BYTES;

    bufferA = device.createBuffer({
      label: `Points Buffer A (${count})`,
      size: pointsBufferSize,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST | GPUBufferUsage.COPY_SRC,
    });

    bufferB = device.createBuffer({
      label: `Points Buffer B (${count})`,
      size: pointsBufferSize,
      usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST | GPUBufferUsage.COPY_SRC,
    });

    const initialData = initPointsData(count);
    device.queue.writeBuffer(bufferA, 0, initialData);
    device.queue.writeBuffer(bufferB, 0, initialData);

    bindGroupAtoB = device.createBindGroup({
      label: "Compute BindGroup A -> B",
      layout: bindGroupLayout,
      entries: [
        { binding: 0, resource: { buffer: uniformsBuffer } },
        { binding: 1, resource: { buffer: bufferA } },
        { binding: 2, resource: { buffer: bufferB } },
      ],
    });

    bindGroupBtoA = device.createBindGroup({
      label: "Compute BindGroup B -> A",
      layout: bindGroupLayout,
      entries: [
        { binding: 0, resource: { buffer: uniformsBuffer } },
        { binding: 1, resource: { buffer: bufferB } },
        { binding: 2, resource: { buffer: bufferA } },
      ],
    });

    pingPong = true;
  }

  setupBuffers(initialPoints);

  function resetPoints(): void {
    const initialData = initPointsData(currentPoints);
    device.queue.writeBuffer(bufferA, 0, initialData);
    device.queue.writeBuffer(bufferB, 0, initialData);
  }

  function setParticleCount(newCount: number): void {
    if (newCount !== currentPoints && newCount > 0) {
      setupBuffers(newCount);
    }
  }

  function writeUniforms(uniformsData: Float32Array<ArrayBuffer>): void {
    device.queue.writeBuffer(uniformsBuffer, 0, uniformsData);
  }

  function step(commandEncoder: GPUCommandEncoder, uniformsData: Float32Array<ArrayBuffer>): void {
    writeUniforms(uniformsData);

    const pass = commandEncoder.beginComputePass({
      label: "Simulation Compute Pass",
    });

    pass.setPipeline(computePipeline);
    pass.setBindGroup(0, pingPong ? bindGroupAtoB : bindGroupBtoA);

    const workgroups = Math.ceil(currentPoints / 64);
    pass.dispatchWorkgroups(workgroups);

    pass.end();

    pingPong = !pingPong;
  }

  function getActiveReadBuffer(): GPUBuffer {
    return pingPong ? bufferA : bufferB;
  }

  const sim: SimulationManager = {
    get numPoints() {
      return currentPoints;
    },
    uniformsBuffer,
    step,
    writeUniforms,
    getActiveReadBuffer,
    resetPoints,
    setParticleCount,
    updateShader,
  };

  activeSimulation = sim;
  return sim;
}

let activeSimulation: SimulationManager | null = null;

if (import.meta.hot) {
  import.meta.hot.accept("./_compute.wgsl", newModule => {
    if (newModule?.["default"] && activeSimulation) {
      activeSimulation.updateShader?.(newModule["default"]);
    }
  });
}

export { createSimulation as SimulationScene };
