// ═══════════════════════════════════════════════════════════════════
//  renderer.ts — Moduł Renderera WebGPU (Geometria Przewodu, Cząstki 3D, HUD)
// ═══════════════════════════════════════════════════════════════════

import renderShaderCode from "./_render.wgsl";
import overlayShaderCode from "./_overlay.wgsl";
import wireShaderCode from "./_wire.wgsl";
import type { Camera3D } from "./camera";

export interface RendererManager {
  render: (
    commandEncoder: GPUCommandEncoder,
    canvasTexture: GPUTexture,
    uniformsBuffer: GPUBuffer,
    activePointsBuffer: GPUBuffer,
    camera: Camera3D,
    numPoints: number,
    showOverlay?: boolean,
  ) => void;
  updateShader?: (newShaderCode: string) => Promise<boolean> | boolean;
  updateOverlayShader?: (newShaderCode: string) => Promise<boolean> | boolean;
}

export class WebGPURenderer implements RendererManager {
  private device: GPUDevice;
  private format: GPUTextureFormat;
  private cameraBuffer: GPUBuffer;
  private cameraData: Float32Array<ArrayBuffer>;

  private simulationBindGroupLayout: GPUBindGroupLayout;
  private uniformOnlyBindGroupLayout: GPUBindGroupLayout;
  private cameraBindGroupLayout: GPUBindGroupLayout;
  private cameraBindGroup: GPUBindGroup;

  private pipelineLayout: GPUPipelineLayout;
  private overlayPipelineLayout: GPUPipelineLayout;
  private wirePipelineLayout: GPUPipelineLayout;

  private renderPipeline!: GPURenderPipeline;
  private overlayPipeline!: GPURenderPipeline;
  private wirePipeline!: GPURenderPipeline;
  private shieldPipeline!: GPURenderPipeline;

  private cachedBuffer: GPUBuffer | null = null;
  private cachedSimulationBindGroup: GPUBindGroup | null = null;
  private cachedUniformBuffer: GPUBuffer | null = null;
  private cachedUniformBindGroup: GPUBindGroup | null = null;

  constructor(device: GPUDevice, format: GPUTextureFormat) {
    this.device = device;
    this.format = format;

    // 1. Bufor Camera Uniforms (viewProj, invViewProj, eye) = 160 bajtów
    const cameraBufferSize = 160;
    this.cameraBuffer = device.createBuffer({
      label: "Camera Uniform Buffer",
      size: cameraBufferSize,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });
    this.cameraData = new Float32Array(cameraBufferSize / 4);

    // 2. BindGroupLayouts
    this.simulationBindGroupLayout = device.createBindGroupLayout({
      label: "Render Simulation BindGroupLayout",
      entries: [
        {
          binding: 0,
          visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT,
          buffer: { type: "uniform" },
        },
        {
          binding: 1,
          visibility: GPUShaderStage.VERTEX,
          buffer: { type: "read-only-storage" },
        },
      ],
    });

    this.uniformOnlyBindGroupLayout = device.createBindGroupLayout({
      label: "Uniform Only BindGroupLayout",
      entries: [
        {
          binding: 0,
          visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT,
          buffer: { type: "uniform" },
        },
      ],
    });

    this.cameraBindGroupLayout = device.createBindGroupLayout({
      label: "Render Camera BindGroupLayout",
      entries: [
        {
          binding: 0,
          visibility: GPUShaderStage.VERTEX | GPUShaderStage.FRAGMENT,
          buffer: { type: "uniform" },
        },
      ],
    });

    this.cameraBindGroup = device.createBindGroup({
      label: "Render Camera BindGroup",
      layout: this.cameraBindGroupLayout,
      entries: [{ binding: 0, resource: { buffer: this.cameraBuffer } }],
    });

    // 3. Pipeline Layouts
    this.pipelineLayout = device.createPipelineLayout({
      label: "Render Pipeline Layout",
      bindGroupLayouts: [this.simulationBindGroupLayout, this.cameraBindGroupLayout],
    });

    this.overlayPipelineLayout = device.createPipelineLayout({
      label: "Overlay Pipeline Layout",
      bindGroupLayouts: [this.uniformOnlyBindGroupLayout],
    });

    this.wirePipelineLayout = device.createPipelineLayout({
      label: "Wire & Shield Pipeline Layout",
      bindGroupLayouts: [this.uniformOnlyBindGroupLayout, this.cameraBindGroupLayout],
    });

    this.initPipeline(renderShaderCode);
    this.initOverlayPipeline(overlayShaderCode);
    this.initWirePipelines(wireShaderCode);
  }

  public initPipeline(shaderSource: string = renderShaderCode): boolean {
    try {
      const shaderModule = this.device.createShaderModule({
        label: "Render Shader Module",
        code: shaderSource,
      });

      this.renderPipeline = this.device.createRenderPipeline({
        label: "Quads & Points Render Pipeline",
        layout: this.pipelineLayout,
        vertex: {
          module: shaderModule,
          entryPoint: "vs_main",
        },
        fragment: {
          module: shaderModule,
          entryPoint: "fs_main",
          targets: [
            {
              format: this.format,
              blend: {
                color: {
                  srcFactor: "src-alpha",
                  dstFactor: "one", // Additive blend dla cząstek
                  operation: "add",
                },
                alpha: {
                  srcFactor: "one",
                  dstFactor: "one",
                  operation: "add",
                },
              },
            },
          ],
        },
        primitive: {
          topology: "triangle-list",
          cullMode: "none",
        },
      });
      return true;
    } catch (err) {
      console.error("Failed to compile render shader:", err);
      return false;
    }
  }

  public initWirePipelines(shaderSource: string = wireShaderCode): boolean {
    try {
      const shaderModule = this.device.createShaderModule({
        label: "Wire & Shield Shader Module",
        code: shaderSource,
      });

      // Centralny przewód miedziany
      this.wirePipeline = this.device.createRenderPipeline({
        label: "Central Wire Render Pipeline",
        layout: this.wirePipelineLayout,
        vertex: {
          module: shaderModule,
          entryPoint: "vs_wire",
        },
        fragment: {
          module: shaderModule,
          entryPoint: "fs_wire",
          targets: [
            {
              format: this.format,
              blend: {
                color: {
                  srcFactor: "src-alpha",
                  dstFactor: "one-minus-src-alpha",
                  operation: "add",
                },
                alpha: {
                  srcFactor: "one",
                  dstFactor: "one-minus-src-alpha",
                  operation: "add",
                },
              },
            },
          ],
        },
        primitive: {
          topology: "triangle-list",
          cullMode: "none",
        },
      });

      // Zewnętrzne pierścienie ekranu
      this.shieldPipeline = this.device.createRenderPipeline({
        label: "Outer Shield Rings Render Pipeline",
        layout: this.wirePipelineLayout,
        vertex: {
          module: shaderModule,
          entryPoint: "vs_shield",
        },
        fragment: {
          module: shaderModule,
          entryPoint: "fs_shield",
          targets: [
            {
              format: this.format,
              blend: {
                color: {
                  srcFactor: "src-alpha",
                  dstFactor: "one", // Additive neon glow
                  operation: "add",
                },
                alpha: {
                  srcFactor: "one",
                  dstFactor: "one",
                  operation: "add",
                },
              },
            },
          ],
        },
        primitive: {
          topology: "triangle-list",
          cullMode: "none",
        },
      });

      return true;
    } catch (err) {
      console.error("Failed to compile wire pipelines:", err);
      return false;
    }
  }

  public initOverlayPipeline(shaderSource: string = overlayShaderCode): boolean {
    try {
      const shaderModule = this.device.createShaderModule({
        label: "Overlay Shader Module",
        code: shaderSource,
      });

      this.overlayPipeline = this.device.createRenderPipeline({
        label: "Fullscreen Overlay & HUD Pipeline",
        layout: this.overlayPipelineLayout,
        vertex: {
          module: shaderModule,
          entryPoint: "vs_overlay",
        },
        fragment: {
          module: shaderModule,
          entryPoint: "fs_overlay",
          targets: [
            {
              format: this.format,
              blend: {
                color: {
                  srcFactor: "src-alpha",
                  dstFactor: "one-minus-src-alpha",
                  operation: "add",
                },
                alpha: {
                  srcFactor: "one",
                  dstFactor: "one-minus-src-alpha",
                  operation: "add",
                },
              },
            },
          ],
        },
        primitive: {
          topology: "triangle-list",
          cullMode: "none",
        },
      });
      return true;
    } catch (err) {
      console.error("Failed to compile overlay shader:", err);
      return false;
    }
  }

  public render(
    commandEncoder: GPUCommandEncoder,
    canvasTexture: GPUTexture,
    uniformsBuffer: GPUBuffer,
    activePointsBuffer: GPUBuffer,
    camera: Camera3D,
    numPoints: number,
    showOverlay: boolean = false,
  ): void {
    // 1. Zapis macierzy kamery 3D do bufora GPU
    this.cameraData.set(camera.viewProjMatrix, 0);
    this.cameraData.set(camera.invViewProjMatrix, 16);
    this.cameraData[32] = camera.eye[0];
    this.cameraData[33] = camera.eye[1];
    this.cameraData[34] = camera.eye[2];
    this.cameraData[35] = 1.0;

    this.device.queue.writeBuffer(this.cameraBuffer, 0, this.cameraData);

    // 2. Cache BindGroups
    if (this.cachedBuffer !== activePointsBuffer || !this.cachedSimulationBindGroup) {
      this.cachedBuffer = activePointsBuffer;
      this.cachedSimulationBindGroup = this.device.createBindGroup({
        label: "Dynamic Simulation BindGroup",
        layout: this.simulationBindGroupLayout,
        entries: [
          { binding: 0, resource: { buffer: uniformsBuffer } },
          { binding: 1, resource: { buffer: activePointsBuffer } },
        ],
      });
    }

    if (this.cachedUniformBuffer !== uniformsBuffer || !this.cachedUniformBindGroup) {
      this.cachedUniformBuffer = uniformsBuffer;
      this.cachedUniformBindGroup = this.device.createBindGroup({
        label: "Uniform Only BindGroup",
        layout: this.uniformOnlyBindGroupLayout,
        entries: [{ binding: 0, resource: { buffer: uniformsBuffer } }],
      });
    }

    // 3. Render Pass
    const pass = commandEncoder.beginRenderPass({
      label: "Main Render Pass",
      colorAttachments: [
        {
          view: canvasTexture.createView(),
          clearValue: { r: 0.02, g: 0.02, b: 0.05, a: 1.0 },
          loadOp: "clear",
          storeOp: "store",
        },
      ],
    });

    // 4. Geometria Przewodu i Ekranu 3D (32 segmenty x 6 wierzchołków = 192 wierzchołki)
    if (this.wirePipeline && this.shieldPipeline && this.cachedUniformBindGroup) {
      pass.setBindGroup(0, this.cachedUniformBindGroup);
      pass.setBindGroup(1, this.cameraBindGroup);

      // A: Centralny przewód miedziany z pulsującym prądem
      pass.setPipeline(this.wirePipeline);
      pass.draw(32 * 6, 1);

      // B: Zewnętrzne pierścienie ekranu (7 instancji wzdłuż kabla)
      pass.setPipeline(this.shieldPipeline);
      pass.draw(32 * 6, 7);
    }

    // 5. Cząstki 3D (Billboarded Quads)
    if (this.cachedSimulationBindGroup) {
      pass.setPipeline(this.renderPipeline);
      pass.setBindGroup(0, this.cachedSimulationBindGroup);
      pass.setBindGroup(1, this.cameraBindGroup);
      pass.draw(6, numPoints);
    }

    // 6. Nakładka HUD / Winieta — WYWOŁYWANA TYLKO GDY WŁĄCZONA (ogromny zysk wydajności)
    if (showOverlay && this.cachedUniformBindGroup) {
      pass.setPipeline(this.overlayPipeline);
      pass.setBindGroup(0, this.cachedUniformBindGroup);
      pass.draw(3, 1);
    }

    pass.end();
  }

  public updateShader = async (newShaderCode: string): Promise<boolean> => {
    return this.initPipeline(newShaderCode);
  };

  public updateOverlayShader = async (newShaderCode: string): Promise<boolean> => {
    return this.initOverlayPipeline(newShaderCode);
  };
}

export function createRenderer(device: GPUDevice, format: GPUTextureFormat): WebGPURenderer {
  return new WebGPURenderer(device, format);
}

