// ═══════════════════════════════════════════════════════════════════
//  main.ts — Główny punkt wejścia: Modularna Pętla WebGPU 3D & HUD
// ═══════════════════════════════════════════════════════════════════

import { initGPUContext, updateCanvasSize } from "./gpuContext";
import { Camera3D } from "./camera";
import { createSimulation, type SimulationManager } from "./simulation";
import { createRenderer, type WebGPURenderer } from "./renderer";
import { OrbitControls } from "./controls";
import { UIManager } from "./ui";

let simulation!: SimulationManager;
let renderer!: WebGPURenderer;
let controls!: OrbitControls;

let simTime = 0;
let stepRequested = false;
const FIXED_STEP_DT = 1 / 60;

// 1. Inicjalizacja Modułu UI i odczyt zapisanych ustawień (localStorage)
const ui = new UIManager(
  {
    onResetSimulation: () => {
      simulation.resetPoints();
      camera.reset();
      simTime = 0;
    },
    onParticleCountChange: (count: number) => {
      simulation.setParticleCount(count);
    },
    onRenderScaleChange: (scale: number) => {
      if (updateCanvasSize(gpu, scale)) {
        camera.setAspect(gpu.width / gpu.height);
      }
    },
    onToggleHUD: () => {
      if (updateCanvasSize(gpu, ui.settings.renderScale)) {
        camera.setAspect(gpu.width / gpu.height);
      }
    },
    onStepFrame: () => {
      stepRequested = true;
    },
  },
  "Inicjalizacja...",
);

// 2. Inicjalizacja Kontekstu WebGPU z uwzględnieniem zapisanej skali renderowania
const gpu = await initGPUContext("canvas", ui.settings.renderScale);

// Przekazanie nazwy wykrytej karty GPU do paska UI
const gpuNameEl = document.getElementById("gpu-device-name");
if (gpuNameEl) {
  gpuNameEl.textContent = gpu.deviceName;
}

// 3. Inicjalizacja Kamery 3D (Roll = 0, pełna swoboda orbit/pan/zoom)
const camera = new Camera3D(gpu.width / gpu.height);
camera.roll = 0.0;

// 4. Inicjalizacja Symulacji (Compute Pipeline, Ping-Pong Buffers)
simulation = createSimulation(gpu.device, ui.settings.particleCount);

// 5. Inicjalizacja Renderera (Geometria przewodu, Quady 3D, Winieta)
renderer = createRenderer(gpu.device, gpu.format);

// 6. Inicjalizacja Kontrolera Myszki, Dotyku i Klawiatury (OrbitControls)
controls = new OrbitControls(gpu.canvas, camera, {
  onResetSimulation: () => {
    simulation.resetPoints();
    camera.reset();
    simTime = 0;
  },
  onToggleFullscreen: () => {
    ui.toggleFullscreen();
  },
  onToggleHUD: () => {
    ui.toggleHUD();
    if (updateCanvasSize(gpu, ui.settings.renderScale)) {
      camera.setAspect(gpu.width / gpu.height);
    }
  },
  onToggleShaderOverlay: () => {
    ui.toggleShaderOverlay();
  },
  onTogglePause: () => {
    ui.togglePause();
  },
  onStepFrame: () => {
    ui.stepFrame();
  },
  onSlower: () => {
    ui.adjustTimeScale(0.8);
  },
  onFaster: () => {
    ui.adjustTimeScale(1.25);
  },
});

// 7. Bufor danych dla Uniforms (80 bajtów = 20 float32)
const uniformsData = new Float32Array(20);
const uniformsUint32 = new Uint32Array(uniformsData.buffer);

// 8. Dopasowanie do zmiany rozmiaru okna lub trybu pełnoekranowego
window.addEventListener("resize", () => {
  if (updateCanvasSize(gpu, ui.settings.renderScale)) {
    camera.setAspect(gpu.width / gpu.height);
  }
});

document.addEventListener("fullscreenchange", () => {
  if (updateCanvasSize(gpu, ui.settings.renderScale)) {
    camera.setAspect(gpu.width / gpu.height);
  }
});

// 9. Pętla animacji i renderingu
let lastTime = performance.now();
let frameCount = 0;
let lastFpsUpdate = performance.now();

function frame(now: number) {
  const rawDt = Math.min((now - lastTime) * 0.001, 0.05);
  lastTime = now;

  // Sprawdzamy czy rozmiar kontenera canvasu uległ zmianie
  if (updateCanvasSize(gpu, ui.settings.renderScale)) {
    camera.setAspect(gpu.width / gpu.height);
  }

  // Kamera: czysty pion, pełna swoboda
  camera.roll = 0.0;
  camera.updateMatrices();

  // Obliczanie czasu symulacji i delta time z uwzględnieniem pauzy, kroku i timeScale
  const isRunning = !ui.isPaused || stepRequested;
  const simDt = !isRunning ? 0 : stepRequested ? FIXED_STEP_DT : Math.min(rawDt * ui.settings.timeScale, 1 / 30);

  if (isRunning) {
    simTime += simDt;
  }

  // Obliczanie statystyk na żywo
  frameCount++;
  const elapsed = now - lastFpsUpdate;
  if (elapsed >= 350) {
    const fps = (frameCount * 1000) / elapsed;
    const ms = elapsed / frameCount;
    ui.updateStats(fps, ms, gpu.width, gpu.height);
    frameCount = 0;
    lastFpsUpdate = now;
  }

  // Wyznaczanie pozycji 3D sondy kursora na płaszczyźnie ogniskowej sceny
  const probe3D = camera.getRayIntersection(controls.mouseX, controls.mouseY);

  // Wypełnienie bufora Uniforms dla Compute i Render (80 bajtów)
  uniformsData[0] = probe3D[0];
  uniformsData[1] = probe3D[1];
  uniformsData[2] = probe3D[2];
  uniformsData[3] = controls.isMouseDown ? 1.0 : 0.0;
  uniformsData[4] = gpu.width;
  uniformsData[5] = gpu.height;
  uniformsData[6] = simTime;
  uniformsData[7] = simDt;
  uniformsUint32[8] = simulation.numPoints;
  uniformsData[9] = ui.settings.gravity * 2.0; // nominalne 1.0g = 1.0 w shaderze
  uniformsData[10] = ui.settings.damping;
  uniformsData[11] = ui.settings.interactionRadius;
  uniformsData[12] = ui.settings.vortexStrength;
  uniformsData[13] = ui.settings.pointSizeMultiplier;
  uniformsData[14] = ui.settings.interactionMode;
  uniformsData[15] = ui.settings.glowIntensity;
  uniformsData[16] = ui.settings.renderScale;
  uniformsData[17] = ui.settings.showShaderOverlay ? 1.0 : 0.0;
  uniformsData[18] = 0.0;
  uniformsData[19] = 0.0;

  // Utworzenie Command Encodera dla klatki
  const commandEncoder = gpu.device.createCommandEncoder({
    label: "Main Frame Command Encoder",
  });

  // 1. COMPUTE PASS: Fizyka cząstek (IN -> OUT Ping-Pong)
  if (isRunning) {
    simulation.step(commandEncoder, uniformsData);
    stepRequested = false;
  } else {
    simulation.writeUniforms(uniformsData);
  }

  // 2. RENDER PASS: Przewód 3D + Ekran koncentryczny + Quads 3D + Opcjonalna Winieta
  const canvasTexture = gpu.context.getCurrentTexture();
  renderer.render(
    commandEncoder,
    canvasTexture,
    simulation.uniformsBuffer,
    simulation.getActiveReadBuffer(),
    camera,
    simulation.numPoints,
    ui.settings.showShaderOverlay,
  );

  // 3. Wysłanie komend do kolejki GPU
  gpu.device.queue.submit([commandEncoder.finish()]);

  requestAnimationFrame(frame);
}

requestAnimationFrame(frame);
