// ═══════════════════════════════════════════════════════════════════
//  camera.ts — Uniwersalna kamera 3D (Orbit, Pan, Zoom) z wgpu-matrix
// ═══════════════════════════════════════════════════════════════════

import { mat4, vec3 } from "wgpu-matrix";

export class Camera3D {
  // Kąty sferyczne (radiany)
  public azimuth: number = 0.0;
  public elevation: number = 0.25;
  public distance: number = 3.5;
  public roll: number = 0.0; // Obrót wokół osi widzenia w radianach (Roll)

  // Cel (punkt na który patrzy kamera)
  public target: [number, number, number] = [0, 0, 0];

  // Macierze i wektory
  public viewMatrix = mat4.create();
  public projectionMatrix = mat4.create();
  public viewProjMatrix = mat4.create();
  public invViewProjMatrix = mat4.create();
  public eye: [number, number, number] = [0, 0, 3.5];

  public fov: number = (60 * Math.PI) / 180;
  public near: number = 0.01;
  public far: number = 100.0;
  public aspect: number = 1.0;

  constructor(aspect: number = 1.0) {
    this.aspect = aspect;
    this.updateMatrices();
  }

  public setAspect(aspect: number): void {
    this.aspect = Math.max(0.01, aspect);
    this.updateMatrices();
  }

  /**
   * Obrót orbitalny kamery wokół punktu docelowego
   */
  public orbit(deltaAzimuth: number, deltaElevation: number): void {
    this.azimuth += deltaAzimuth;
    this.elevation = Math.max(-Math.PI * 0.48, Math.min(Math.PI * 0.48, this.elevation + deltaElevation));
    this.updateMatrices();
  }

  /**
   * Płynny zoom kamery (przybliżanie / oddalanie)
   */
  public zoom(factor: number): void {
    this.distance = Math.max(0.2, Math.min(50.0, this.distance * factor));
    this.updateMatrices();
  }

  /**
   * Przesunięcie płaszczyzny widoku (Pan)
   */
  public pan(deltaX: number, deltaY: number): void {
    const panSpeed = this.distance * 0.0015;

    // Wyznacz wektor 'right' i 'up' w przestrzeni kamery
    const forward = vec3.normalize(vec3.subtract(this.target, this.eye));
    const right = vec3.normalize(vec3.cross(forward, [0, 1, 0]));
    const up = vec3.normalize(vec3.cross(right, forward));

    const moveRight = vec3.mulScalar(right, -deltaX * panSpeed);
    const moveUp = vec3.mulScalar(up, deltaY * panSpeed);
    const offset = vec3.add(moveRight, moveUp);

    this.target = [
      this.target[0] + (offset[0] ?? 0),
      this.target[1] + (offset[1] ?? 0),
      this.target[2] + (offset[2] ?? 0),
    ];

    this.updateMatrices();
  }

  /**
   * Reset pozycji kamery
   */
  public reset(): void {
    this.azimuth = 0.0;
    this.elevation = 0.25;
    this.distance = 3.5;
    this.roll = 0.0;
    this.target = [0, 0, 0];
    this.updateMatrices();
  }

  /**
   * Przeliczenie macierzy widoku i rzutowania
   */
  public updateMatrices(): void {
    // Oblicz pozycję oka ze współrzędnych sferycznych
    const cosElev = Math.cos(this.elevation);
    const sinElev = Math.sin(this.elevation);
    const cosAzim = Math.cos(this.azimuth);
    const sinAzim = Math.sin(this.azimuth);

    this.eye = [
      this.target[0] + this.distance * cosElev * sinAzim,
      this.target[1] + this.distance * sinElev,
      this.target[2] + this.distance * cosElev * cosAzim,
    ];

    // Macierz widoku (Look-At)
    mat4.lookAt(this.eye, this.target, [0, 1, 0], this.viewMatrix);

    // Zastosowanie obrotu Roll (np. 90° / -90° w zależności od orientacji telefonu)
    if (Math.abs(this.roll) > 0.0001) {
      mat4.rotateZ(this.viewMatrix, this.roll, this.viewMatrix);
    }

    // Macierz rzutowania perspektywicznego
    mat4.perspective(this.fov, this.aspect, this.near, this.far, this.projectionMatrix);

    // Połączona macierz widoku i rzutowania (View-Projection)
    mat4.multiply(this.projectionMatrix, this.viewMatrix, this.viewProjMatrix);

    // Odwrotna macierz (przydatna do raycastingu lub unprojectingu)
    mat4.invert(this.viewProjMatrix, this.invViewProjMatrix);
  }

  /**
   * Wyznacza punkt w przestrzeni 3D odpowiadający znormalizowanym współrzędnym ekranu [-1, 1]
   * na płaszczyźnie przecinającej punkt docelowy (target) kamery.
   */
  public getRayIntersection(ndcX: number, ndcY: number): [number, number, number] {
    const near = vec3.transformMat4([ndcX, ndcY, 0.0], this.invViewProjMatrix);
    const far = vec3.transformMat4([ndcX, ndcY, 1.0], this.invViewProjMatrix);
    const dir = vec3.normalize(vec3.subtract(far, near));

    const viewDir = vec3.normalize(vec3.subtract(this.target, this.eye));
    const denom = vec3.dot(dir, viewDir);

    if (Math.abs(denom) > 1e-4) {
      const t = vec3.dot(vec3.subtract(this.target, this.eye), viewDir) / denom;
      const hit = vec3.add(this.eye, vec3.mulScalar(dir, t));
      return [hit[0] ?? 0, hit[1] ?? 0, hit[2] ?? 0];
    }

    return [this.target[0], this.target[1], this.target[2]];
  }
}
